module longest_repeated_substring (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr [0:15],\n    input wire [4:0] len,\n    output reg [7:0] result [0:15],\n    output reg [4:0] out_len,\n    output reg done\n);\n\n// State declarations\nlocalparam [2:0] IDLE      = 3'd0;\nlocalparam [2:0] CHECK_L   = 3'd1;\nlocalparam [2:0] COMPARE   = 3'd2;\nlocalparam [2:0] NEXT_J    = 3'd3;\nlocalparam [2:0] NEXT_I    = 3'd4;\nlocalparam [2:0] UPDATE    = 3'd5;\nlocalparam [2:0] FINISH    = 3'd6;\n\nreg [2:0] state;\nreg [4:0] L;\nreg [4:0] i, j, k;\nreg [4:0] count;\nreg [7:0] best_chars [0:15];\nreg [4:0] best_length;\nreg match_flag;\nreg [(16*8)-1:0] str_buffer;\ninteger m;\n\n// Temporary comparison register\nreg [7:0] curr_char1, curr_char2;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Reset all registers\n        state <= IDLE;\n        done <= 1'b0;\n        L <= 5'd0;\n        i <= 5'd0;\n        j <= 5'd0;\n        k <= 5'd0;\n        count <= 5'd0;\n        match_flag <= 1'b0;\n        best_length <= 5'd0;\n        out_len <= 5'd0;\n        str_buffer <= 128'd0;\n        curr_char1 <= 8'd0;\n        curr_char2 <= 8'd0;\n        for (m = 0; m < 16; m = m + 1) begin\n            result[m] <= 8'd0;\n            best_chars[m] <= 8'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    // Initialize with buffer length\n                    L <= (len > 16) ? 16 : len;\n                    best_length <= 5'd0;\n                    out_len <= 5'd0;\n                    count <= 5'd0;\n                    i <= 5'd0;\n                    j <= 5'd1;\n                    k <= 5'd0;\n                    match_flag <= 1'b0;\n                    state <= CHECK_L;\n\n                    // Flatten array to packed for easier access\n                    for (m = 0; m < 16; m = m + 1) begin\n                        str_buffer[(m*8)+:8] <= arr[m];\n                    end\n                end\n            end\n\n            CHECK_L: begin\n                if (L >= 2) begin\n                    state <= COMPARE;\n                end else begin\n                    // Output best found or single char\n                    if (best_length > 0) begin\n                        out_len <= best_length;\n                        for (m = 0; m < 16; m = m + 1) begin\n                            result[m] <= (m < best_length) ? best_chars[m] : 8'd0;\n                        end\n                    end else if (len > 0) begin\n                        out_len <= 5'd1;\n                        result[0] <= arr[0];\n                        for (m = 1; m < 16; m = m + 1) begin\n                            result[m] <= 8'd0;\n                        end\n                    end\n                    done <= 1'b1;\n                    state <= FINISH;\n                end\n            end\n\n            COMPARE: begin\n                if (k < L) begin\n                    // Get characters using packed buffer\n                    curr_char1 <= str_buffer[((i + k)*8)+:8];\n                    curr_char2 <= str_buffer[((j + k)*8)+:8];\n                    k <= k + 5'd1;\n                end else begin\n                    k <= 5'd0;\n                    state <= NEXT_J;\n\n                    // Full substring matched\n                    if (curr_char1 == curr_char2) begin\n                        match_flag <= 1'b1;\n                        state <= UPDATE;\n                    end\n                end\n            end\n\n            NEXT_J: begin\n                if ((j + 1) <= (len - L)) begin\n                    j <= j + 5'd1;\n                    state <= COMPARE;\n                end else begin\n                    state <= NEXT_I;\n                end\n            end\n\n            NEXT_I: begin\n                if ((i + 1) <= (len - L - 1)) begin\n                    i <= i + 5'd1;\n                    j <= i + 5'd1;\n                    state <= COMPARE;\n                end else begin\n                    // Decrease substring length\n                    L <= L - 5'd1;\n                    i <= 5'd0;\n                    j <= 5'd1;\n                    state <= CHECK_L;\n                end\n            end\n\n            UPDATE: begin\n                // Check if better match found\n                if ((L > best_length) || ((L == best_length) && check_lex_order(i))) begin\n                    best_length <= L;\n                    for (m = 0; m < L; m = m + 1) begin\n                        best_chars[m] <= str_buffer[((i + m)*8)+:8];\n                    end\n                    // Clear remaining\n                    for (m = L; m < 16; m = m + 1) begin\n                        best_chars[m] <= 8'd0;\n                    end\n                end\n                match_flag <= 1'b0;\n                state <= NEXT_J;\n            end\n\n            FINISH: begin\n                done <= 1'b1;\n                if (!start) state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\n// Lexicographical order check function\nfunction automatic check_lex_order;\n    input [4:0] idx;\n    integer n;\n    begin\n        check_lex_order = 1'b0;\n        for (n = 0; n < best_length; n = n + 1) begin\n            if (best_chars[n] != str_buffer[((idx + n)*8)+:8]) begin\n                check_lex_order = (best_chars[n] > str_buffer[((idx + n)*8)+:8]);\n                break;\n            end\n        end\n    end\nendfunction\n\nendmodule